// ─── Admin: Migrate offline receipts to SRUBF-O/ series ──────────────────────
app.post("/make-server-a0af4170/admin/migrate-offline-receipts", async (c) => {
  try {
    const authUser = resolveAuthUser(c);
    if (!authUser || !isAdmin(authUser.email)) return c.json({ error: "Admin access required" }, 401);

    const all = await kv.getByPrefix("donation:");
    const toMigrate = (all as any[])
      .filter((d: any) => {
        const isOffline = d.paymentMode === "Offline" || d.userId === "offline" || (!d.paymentId?.startsWith("pay_"));
        return isOffline && d.receiptNo?.startsWith("SRUBF/") && !d.receiptNo?.startsWith("SRUBF-O/");
      })
      .sort((a: any, b: any) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());

    if (toMigrate.length === 0) return c.json({ success: true, migrated: 0 });

    const now = new Date();
    const fyStart = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;
    const fy = `${fyStart}-${String(fyStart + 1).slice(2)}`;
    const offlineKey = `receipt_seq_offline:${fy}`;
    let counter = ((await kv.get(offlineKey)) as number | null) || 0;

    for (const d of toMigrate) {
      counter++;
      const newReceipt = `SRUBF-O/${fy}/${String(counter).padStart(6, "0")}`;
      await kv.set(`donation:${d.id}`, { ...d, receiptNo: newReceipt });
    }
    await kv.set(offlineKey, counter);
    console.log(`[migrate] Updated ${toMigrate.length} offline receipts to SRUBF-O series, counter=${counter}`);
    return c.json({ success: true, migrated: toMigrate.length, newCounter: counter });
  } catch (e: any) { return c.json({ error: String(e) }, 500); }
});

// ─── Admin: Fix offline receipt sequence (visible entries only) ───────────────
app.post("/make-server-a0af4170/admin/fix-offline-receipt-sequence", async (c) => {
  try {
    const authUser = resolveAuthUser(c);
    if (!authUser || !isAdmin(authUser.email)) return c.json({ error: "Admin access required" }, 401);

    // June 20 2026 00:00 IST = June 19 2026 18:30 UTC
    const VISIBLE_CUTOFF = new Date("2026-06-19T18:30:00.000Z");
    const now = new Date();
    const fyStart = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;
    const fy = `${fyStart}-${String(fyStart + 1).slice(2)}`;

    const all = await kv.getByPrefix("donation:");
    const visibleOffline = (all as any[])
      .filter((d: any) => {
        const isOffline = d.paymentMode === "Offline" || d.userId === "offline" || (!d.paymentId?.startsWith("pay_"));
        return isOffline && new Date(d.createdAt) >= VISIBLE_CUTOFF;
      })
      .sort((a: any, b: any) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());

    const offlineKey = `receipt_seq_offline:${fy}`;
    let counter = 0;
    for (const d of visibleOffline) {
      counter++;
      const newReceipt = `SRUBF-O/${fy}/${String(counter).padStart(6, "0")}`;
      await kv.set(`donation:${d.id}`, { ...d, receiptNo: newReceipt });
    }
    await kv.set(offlineKey, counter);
    console.log(`[fix-seq] Re-numbered ${counter} visible offline receipts from SRUBF-O/000001`);
    return c.json({ success: true, renumbered: counter });
  } catch (e: any) { return c.json({ error: String(e) }, 500); }
});

// ═══════════════ RAZORPAY ═════════════════════════════════════════════════════
app.post("/make-server-a0af4170/razorpay/create-order", async (c) => {
  try {
    const { amount, currency = "INR", receipt: rec } = await c.req.json();
    if (!amount || amount < 1) return c.json({ error: "Invalid amount" }, 400);
    const keyId = Deno.env.get("RAZORPAY_KEY_ID");
    const keySecret = Deno.env.get("RAZORPAY_KEY_SECRET");
    if (!keyId || !keySecret) {
      console.log("[razorpay] Keys missing — returning mock order");
      return c.json({ orderId: `order_MOCK${Date.now()}`, amount, currency, key: keyId || "rzp_test_mock" });
    }
    const credentials = btoa(`${keyId}:${keySecret}`);
    const res = await fetch("https://api.razorpay.com/v1/orders", {
      method: "POST",
      headers: { "Authorization": `Basic ${credentials}`, "Content-Type": "application/json" },
      body: JSON.stringify({ amount: Math.round(amount * 100), currency, receipt: rec || `AKF-${Date.now()}` }),
    });
    const data = await res.json();
    if (!res.ok) return c.json({ error: data?.error?.description || "Razorpay order creation failed" }, 500);
    console.log("[razorpay] Order created:", data.id);
    return c.json({ orderId: data.id, amount: data.amount, currency: data.currency, key: keyId });
  } catch (e) { return c.json({ error: "Order creation failed: " + e }, 500); }
});

app.post("/make-server-a0af4170/razorpay/verify", async (c) => {
  try {
    const { razorpay_order_id, razorpay_payment_id, razorpay_signature } = await c.req.json();
    const keySecret = Deno.env.get("RAZORPAY_KEY_SECRET");
    if (!keySecret) return c.json({ verified: true });
    const body = razorpay_order_id + "|" + razorpay_payment_id;
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey("raw", encoder.encode(keySecret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
    const signature = await crypto.subtle.sign("HMAC", key, encoder.encode(body));
    const hexSignature = Array.from(new Uint8Array(signature)).map(b => b.toString(16).padStart(2, "0")).join("");
    const verified = hexSignature === razorpay_signature;
    console.log("[razorpay] Signature verified:", verified, razorpay_payment_id);
    return c.json({ verified });
  } catch (e) { console.log("[razorpay] Verify error:", e); return c.json({ verified: true }); }
});

